import type { CSSObject } from 'styled-components';

import Colors from '@dynatrace/strato-design-tokens/colors';

import type { ColorOptionsType } from '../types/color.js';
import type { VariantOptionsType } from '../types/variant.js';

export function _getColorStyles(
  $color: ColorOptionsType,
  $variant: VariantOptionsType,
  disabled: boolean,
): CSSObject {
  let styles = {};
  if (disabled) {
    const CapitalizedVariant = `${$color.charAt(0).toUpperCase()}${$color.slice(
      1,
    )}` as Capitalize<ColorOptionsType>;
    styles = {
      color:
        Colors.Text[$color === 'critical' ? 'Critical' : 'Neutral'].Disabled,
      backgroundColor:
        $variant === 'default'
          ? 'transparent'
          : Colors.Background.Field[CapitalizedVariant].Disabled,
    };
  } else {
    switch ($color) {
      case 'primary':
        if ($variant === 'accent') {
          styles = {
            backgroundColor: Colors.Background.Field.Primary.Accent,
            '&:hover': {
              backgroundColor: Colors.Background.Field.Primary.AccentHover,
            },
            '&:active': {
              backgroundColor: Colors.Background.Field.Primary.AccentActive,
            },
            color: Colors.Text.OnAccent.Default,
          };
        } else {
          styles = {
            backgroundColor:
              $variant === 'emphasized'
                ? Colors.Background.Field.Primary.Emphasized
                : Colors.Background.Field.Primary.Default,
            '&:hover': {
              backgroundColor: Colors.Background.Field.Primary.DefaultHover,
            },
            '&:active': {
              backgroundColor: Colors.Background.Field.Primary.DefaultActive,
            },
            color: Colors.Text.Primary.Default,
          };
        }
        break;
      case 'success':
        if ($variant === 'accent') {
          styles = {
            backgroundColor: Colors.Background.Field.Success.Accent,
            '&:hover': {
              backgroundColor: Colors.Background.Field.Success.AccentHover,
            },
            '&:active': {
              backgroundColor: Colors.Background.Field.Success.AccentActive,
            },
            color: Colors.Text.OnAccent.Default,
          };
        } else {
          styles = {
            backgroundColor:
              $variant === 'emphasized'
                ? Colors.Background.Field.Success.Emphasized
                : Colors.Background.Field.Success.Default,
            '&:hover': {
              backgroundColor: Colors.Background.Field.Success.DefaultHover,
            },
            '&:active': {
              backgroundColor: Colors.Background.Field.Success.DefaultActive,
            },
            color: Colors.Text.Success.Default,
          };
        }
        break;
      case 'warning':
        if ($variant === 'accent') {
          styles = {
            backgroundColor: Colors.Background.Field.Warning.Accent,
            '&:hover': {
              backgroundColor: Colors.Background.Field.Warning.AccentHover,
            },
            '&:active': {
              backgroundColor: Colors.Background.Field.Warning.AccentActive,
            },
            color: Colors.Text.OnAccent.Default,
          };
        } else {
          styles = {
            backgroundColor:
              $variant === 'emphasized'
                ? Colors.Background.Field.Warning.Emphasized
                : Colors.Background.Field.Warning.Default,
            '&:hover': {
              backgroundColor: Colors.Background.Field.Warning.DefaultHover,
            },
            '&:active': {
              backgroundColor: Colors.Background.Field.Warning.DefaultActive,
            },
            color: Colors.Text.Warning.Default,
          };
        }
        break;
      case 'critical':
        if ($variant === 'accent') {
          styles = {
            backgroundColor: Colors.Background.Field.Critical.Accent,
            '&:hover': {
              backgroundColor: Colors.Background.Field.Critical.AccentHover,
            },
            '&:active': {
              backgroundColor: Colors.Background.Field.Critical.AccentActive,
            },
            color: Colors.Text.OnAccent.Default,
          };
        } else {
          styles = {
            backgroundColor:
              $variant === 'emphasized'
                ? Colors.Background.Field.Critical.Emphasized
                : Colors.Background.Field.Critical.Default,
            '&:hover': {
              backgroundColor: Colors.Background.Field.Critical.DefaultHover,
            },
            '&:active': {
              backgroundColor: Colors.Background.Field.Critical.DefaultActive,
            },
            color: Colors.Text.Critical.Default,
          };
        }
        break;
      case 'neutral':
      default:
        if ($variant === 'accent') {
          styles = {
            backgroundColor: Colors.Background.Field.Neutral.Accent,
            '&:hover': {
              backgroundColor: Colors.Background.Field.Neutral.AccentHover,
            },
            '&:active': {
              backgroundColor: Colors.Background.Field.Neutral.AccentActive,
            },
            color: Colors.Text.OnAccent.Default,
          };
        } else {
          styles = {
            backgroundColor:
              $variant === 'emphasized'
                ? Colors.Background.Field.Neutral.Emphasized
                : Colors.Background.Field.Neutral.Default,
            '&:hover': {
              backgroundColor: Colors.Background.Field.Neutral.DefaultHover,
            },
            '&:active': {
              backgroundColor: Colors.Background.Field.Neutral.DefaultActive,
            },
            color: Colors.Text.Neutral.Default,
          };
        }
        break;
    }
  }

  return styles;
}
